package com.weaponsregistration.inventory.model;import com.weaponsregistration.core.model.*;import jakarta.persistence.*;import java.time.LocalDate;
@Entity@Table(name="erp_expiration_record")public class ExpirationRecord extends CoreEntity{@ManyToOne(optional=false)@JoinColumn(name="organization_id",nullable=false)public Organization organization;@ManyToOne@JoinColumn(name="unit_id")public OrganizationalUnit unit;@ManyToOne@JoinColumn(name="asset_id")public AssetItem asset;@ManyToOne@JoinColumn(name="lot_id")public StockLot lot;@Column(nullable=false)public String type;@Column(nullable=false)public LocalDate expirationDate;@Column(nullable=false)public String status;}
